// Match only unambiguous exact titles; never use popularity as identity evidence.
const normalizeTitle = s => String(s||'').normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');
function chooseCandidate(record,data){
 const title=normalizeTitle(record.title),year=(record.meta||'').match(/((?:19|20)\d{2})年製作/)?.[1];
 if(data.total_pages>1)return {reason:'候補が多いため要確認'};
 const exact=(data.results||[]).filter(m=>[m.title,m.original_title].some(t=>normalizeTitle(t)===title));
 const candidates=year?exact.filter(m=>m.release_date?.slice(0,4)===year):exact;
 if(candidates.length!==1)return {reason:candidates.length>1?'同名作品の候補が複数':'作品名・公開年の完全一致なし'};
 if(!year&&title.length<=3)return {reason:'短い作品名・公開年なしのため要確認'};
 return {candidate:candidates[0],evidence:year?'作品名と製作年が完全一致':'作品名が完全一致・全検索結果内で候補が1件'};
}
const txt=v=>typeof v==='string'?v:'';
function metadata(data){
 const now=Date.now(),jp=data['watch/providers']?.results?.JP,groups={};
 for(const k of ['flatrate','rent','buy','free','ads'])groups[k]=[...new Set((jp?.[k]||[]).map(p=>txt(p.provider_name)).filter(Boolean))];
 const dates=(data.release_dates?.results||[]).find(r=>r.iso_3166_1==='JP')?.release_dates||[];
 return {source:'TMDB',id:data.id,title:txt(data.title),originalTitle:txt(data.original_title),releaseDate:txt(data.release_date),japanTheatricalDate:dates.filter(r=>[2,3].includes(r.type)).map(r=>r.release_date.slice(0,10)).sort()[0]||'',runtime:data.runtime||null,directors:(data.credits?.crew||[]).filter(p=>p.job==='Director').map(p=>txt(p.name)),cast:(data.credits?.cast||[]).slice(0,12).map(p=>({name:txt(p.name),character:txt(p.character)})),genres:(data.genres||[]).map(g=>txt(g.name)),overview:txt(data.overview),poster:/^\/[\w.-]+$/.test(data.poster_path||'')?'https://image.tmdb.org/t/p/w500'+data.poster_path:'',checkedAt:now,providers:data['watch/providers']?{...groups,checkedAt:now,region:'JP',link:txt(jp?.link)}:null,providerError:!data['watch/providers']};
}
const protectedRecord = record => {const {movie,enrichment,_revision,...rest}=record;return rest;};
async function enrichBatch(request,env){
 const url=new URL(request.url);
 if(request.method==='GET'){
  const {results}=await env.DB.prepare('SELECT f.id,f.body,s.body AS original FROM films f LEFT JOIN enrichment_snapshots s ON f.id=s.id').all();
  let linked=0,review=0,errors=0,posters=0,protectedMismatch=0,processed=0;
  for(const row of results){const r=JSON.parse(row.body);if(r.enrichment){processed++;if(r.enrichment.status==='linked')linked++;else if(r.enrichment.status==='review')review++;else errors++;}if(r.movie?.poster)posters++;if(row.original&&JSON.stringify(protectedRecord(r))!==JSON.stringify(protectedRecord(JSON.parse(row.original))))protectedMismatch++;}
  return json({total:results.length,processed,linked,review,errors,posters,protectedMismatch});
 }
 if(request.method!=='POST')return json({error:'利用できません。'},405);
 const input=await request.json(),cursor=typeof input.cursor==='string'?input.cursor:'';
 const {results}=await env.DB.prepare('SELECT id,body,revision FROM films WHERE id > ? ORDER BY id LIMIT 5').bind(cursor).all();
 const key=await storedKey(env);if(!key)return json({error:'映画情報の共通接続が必要です。'},503);
 const outcomes=await Promise.all(results.map(async row=>{
  const record=JSON.parse(row.body);
  if(record.enrichment||record.movie?.id)return {id:row.id,status:'skip'};
  try{
   const search=await upstream('search/movie',key,[['query',record.title],['include_adult','false'],['region','JP']]);if(!search.ok)throw new Error('search');
   const data=await search.json(),match=chooseCandidate(record,data);let movie;
   if(match.candidate){const detail=await upstream('movie/'+match.candidate.id,key,[['append_to_response','credits,release_dates,watch/providers']]);if(!detail.ok)throw new Error('details');const d=await detail.json();if(d.id!==match.candidate.id)throw new Error('identity');movie=metadata(d);}
   const enrichment={status:movie?'linked':'review',reason:match.evidence||match.reason,checkedAt:Date.now(),candidates:movie?[]:(data.results||[]).filter(m=>normalizeTitle(m.title)===normalizeTitle(record.title)||normalizeTitle(m.original_title)===normalizeTitle(record.title)).slice(0,6).map(m=>({id:m.id,title:m.title,year:(m.release_date||'').slice(0,4)}))};
   const next={...record,...(movie?{movie}:{}),enrichment};
   // The snapshot and optimistic update are one transaction. Concurrent edits win.
   const saved=await env.DB.batch([env.DB.prepare('INSERT OR IGNORE INTO enrichment_snapshots(id,body,revision) VALUES(?,?,?)').bind(row.id,row.body,row.revision),env.DB.prepare('UPDATE films SET body=?,revision=revision+1 WHERE id=? AND revision=?').bind(JSON.stringify(next),row.id,row.revision)]);
   return {id:row.id,status:saved[1].meta.changes===1?enrichment.status:'conflict'};
  }catch{return {id:row.id,status:'error'};}
 }));
 return json({cursor:results.at(-1)?.id||cursor,done:results.length<5,outcomes});
}

// Passphrase gate for the Cloudflare deployment (added at migration time).
// The app itself still checks for the ChatGPT Sites identity header; after a
// successful passphrase login this gate injects that header, so worker/api.mjs
// and the client stay unchanged. Active only when both AUTH_SECRET and
// AUTH_PASSPHRASE are set as Worker secrets; otherwise it is skipped.
async function yoinAuthToken(env) {
  const key = await crypto.subtle.importKey('raw', new TextEncoder().encode(env.AUTH_SECRET), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode('yoin-owner-v1'));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
}
function yoinCookieValue(request, name) {
  const raw = request.headers.get('Cookie') || '';
  for (const part of raw.split(';')) {
    const i = part.indexOf('=');
    if (i > 0 && part.slice(0, i).trim() === name) return part.slice(i + 1).trim();
  }
  return '';
}
function yoinSame(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function yoinLoginPage(error) {
  return `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>余韻 — ログイン</title><style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;background:#f6f3ec;font-family:sans-serif;color:#223}.card{background:#fff;border:1px solid #ddd6c4;border-radius:16px;padding:32px 28px;max-width:340px;width:88%;box-shadow:0 8px 30px rgba(60,50,20,.08)}h1{font-size:28px;margin:0 0 4px;letter-spacing:.2em}.sub{color:#667;font-size:13px;margin:0 0 20px}label{font-size:13px;color:#445;display:block;margin-bottom:6px}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #c9c2ae;border-radius:10px;font-size:16px}button{margin-top:16px;width:100%;padding:12px;border:0;border-radius:10px;background:#20503c;color:#fff;font-size:16px;cursor:pointer}.err{color:#a33;font-size:13px;margin:0 0 12px}</style></head><body><main class="card"><h1>余韻</h1><p class="sub">映画の記録 — 本人専用です</p>${error ? '<p class="err">合言葉が違います。もう一度お試しください。</p>' : ''}<form method="post" action="/login"><label for="p">合言葉</label><input id="p" name="passphrase" type="password" autocomplete="current-password" required autofocus><button type="submit">開く</button></form></main></body></html>`;
}
async function yoinGate(request, env, path) {
  if (path === '/login') {
    if (request.method === 'POST') {
      const form = await request.formData().catch(() => null);
      const pass = form ? String(form.get('passphrase') || '') : '';
      if (yoinSame(pass, env.AUTH_PASSPHRASE)) {
        const token = await yoinAuthToken(env);
        return new Response(null, { status: 303, headers: { 'Location': '/', 'Set-Cookie': 'yoin_auth=' + token + '; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=15552000', 'Cache-Control': 'no-store' } });
      }
      return new Response(yoinLoginPage(true), { status: 401, headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
    }
    return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
  }
  if (path === '/logout') {
    return new Response(null, { status: 303, headers: { 'Location': '/login', 'Set-Cookie': 'yoin_auth=; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=0', 'Cache-Control': 'no-store' } });
  }
  const token = await yoinAuthToken(env);
  if (yoinSame(yoinCookieValue(request, 'yoin_auth'), token)) {
    const headers = new Headers(request.headers);
    headers.set('oai-authenticated-user-id', 'owner');
    return new Request(request, { headers });
  }
  if (path.startsWith('/api/')) return Response.json({ error: 'ログインが必要です。ページを開き直してログインしてください。' }, { status: 401, headers: { 'Cache-Control': 'no-store' } });
  return new Response(yoinLoginPage(false), { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' } });
}

const json = (data, status = 200) => Response.json(data, {status, headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function validate(r) {
  return r && typeof r.id==='string' && r.id.length>0 && r.id.length<=200 && typeof r.title==='string' && r.title.trim() && r.title.length<=1000 && ['watched','want'].includes(r.status) && Number.isFinite(r.rating) && r.rating>=0 && r.rating<=5 && Number.isFinite(r.updated) && ['date','meta','review'].every(k=>typeof r[k]==='string' && r[k].length<=100000);
}
function clean(r) { const {_revision,...body}=r; return body; }
async function api(request, env) {
  if(!request.headers.get('oai-authenticated-user-id'))return json({error:'同じChatGPTアカウントでログインしてください。'},401);
  if(new URL(request.url).pathname.startsWith('/api/tmdb'))return tmdb(request,env);
  if(!env.DB)return json({error:'保存先の準備が完了していません。'},503);
  const url=new URL(request.url);
  if(request.method!=='GET' && (request.headers.get('Origin')!==url.origin || !request.headers.get('Content-Type')?.startsWith('application/json')))return json({error:'この画面から操作してください。'},403);
  try {
    if(url.pathname==='/api/enrich')return await enrichBatch(request,env);
    if(url.pathname==='/api/records' && request.method==='GET') {
      const {results}=await env.DB.prepare('SELECT body, revision FROM films ORDER BY id').all();
      return json({records:results.map(r=>({...JSON.parse(r.body),_revision:r.revision}))});
    }
    if(url.pathname==='/api/import' && request.method==='POST') {
      const data=await request.json();
      if(!Array.isArray(data.records)||data.records.length>10000||!data.records.every(validate)||new Set(data.records.map(r=>r.id)).size!==data.records.length)return json({error:'記録の形式が正しくありません。'},400);
      let added=0;
      for(let i=0;i<data.records.length;i+=50){
        const results=await env.DB.batch(data.records.slice(i,i+50).map(r=>env.DB.prepare('INSERT OR IGNORE INTO films (id, body, revision) VALUES (?, ?, 1)').bind(r.id,JSON.stringify(clean(r)))));
        added+=results.reduce((n,r)=>n+(r.meta?.changes||0),0);
      }
      return json({added});
    }
    if(url.pathname.startsWith('/api/records/')) {
      const id=decodeURIComponent(url.pathname.slice('/api/records/'.length));const data=await request.json();
      if(!Number.isInteger(data._revision)||data._revision<1)return json({error:'最新の画面を開き直してから編集してください。'},409);
      let result;
      if(request.method==='PUT') {
        if(!validate(data)||data.id!==id)return json({error:'記録の形式が正しくありません。'},400);
        result=await env.DB.prepare('UPDATE films SET body = ?, revision = revision + 1 WHERE id = ? AND revision = ?').bind(JSON.stringify(clean(data)),id,data._revision).run();
      }else if(request.method==='DELETE') {
        result=await env.DB.prepare('DELETE FROM films WHERE id = ? AND revision = ?').bind(id,data._revision).run();
      }else return json({error:'この操作は利用できません。'},405);
      if(result.meta.changes!==1)return json({error:'別の端末で更新されています。この画面を開き直してから編集してください。入力中の感想はコピーして残せます。'},409);
      return json({saved:true});
    }
    return json({error:'見つかりません。'},404);
  }catch(e){return json({error:'同期できませんでした。通信状態を確認してもう一度お試しください。'},503);}
}

const TMDB_HOST='https://api.themoviedb.org/3/';
async function cipherKey(env){return crypto.subtle.importKey('raw',Uint8Array.from(atob(env.TMDB_CONFIG_KEY),c=>c.charCodeAt(0)), 'AES-GCM',false,['encrypt','decrypt']);}
async function storedKey(env){const row=await env.DB.prepare("SELECT body FROM app_settings WHERE name = 'tmdb'").first();if(!row)return '';const data=JSON.parse(row.body);return new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:Uint8Array.from(data.iv)},await cipherKey(env),Uint8Array.from(data.data)));}
async function upstream(path,key,params){const target=new URL(TMDB_HOST+path);target.searchParams.set('language','ja-JP');for(const [k,v] of params)if(['query','region','include_adult','include_video','page','watch_region','with_watch_providers','with_watch_monetization_types','sort_by','append_to_response','with_release_type','release_date.gte','release_date.lte'].includes(k)&&v.length<=300)target.searchParams.set(k,v);const headers={accept:'application/json'};if(/^[a-f0-9]{32}$/i.test(key))target.searchParams.set('api_key',key);else headers.Authorization='Bearer '+key;return fetch(target,{headers,signal:AbortSignal.timeout(15000)});}
// Calendar arithmetic uses the Tokyo calendar date, independent of server timezone.
function japanWeek(now = new Date()) {
 const today = new Date(now.toLocaleDateString('en-CA', {timeZone:'Asia/Tokyo'}) + 'T00:00:00Z');
 const monday = new Date(today);
 monday.setUTCDate(today.getUTCDate() - (today.getUTCDay() + 6) % 7);
 const sunday = new Date(monday);
 sunday.setUTCDate(monday.getUTCDate() + 6);
 return {start:monday.toISOString().slice(0,10),end:sunday.toISOString().slice(0,10)};
}
async function tmdb(request,env){
 const url=new URL(request.url);
 try{
  if(!env.DB||!env.TMDB_CONFIG_KEY)return json({error:'共通接続を準備しています。'},503);
  if(url.pathname==='/api/tmdb/connection'){
   if(request.method==='GET')return json({connected:!!(await storedKey(env))});
   if(request.method!=='POST'||request.headers.get('Origin')!==url.origin||!request.headers.get('Content-Type')?.startsWith('application/json'))return json({error:'この画面から操作してください。'},403);
   const data=await request.json();const key=typeof data.credential==='string'?data.credential.trim():'';
   if(!key||key.length>4096)return json({error:'接続キーを確認してください。'},400);
   const check=await upstream('configuration',key,[]);if(!check.ok)return json({error:'TMDBの接続キーを確認してください。'},400);
   const iv=crypto.getRandomValues(new Uint8Array(12));const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},await cipherKey(env),new TextEncoder().encode(key));
   await env.DB.prepare("INSERT INTO app_settings(name,body) VALUES('tmdb',?) ON CONFLICT(name) DO UPDATE SET body=excluded.body").bind(JSON.stringify({iv:[...iv],data:[...new Uint8Array(encrypted)]})).run();return json({connected:true});
  }
  if(request.method!=='GET')return json({error:'利用できません。'},405);
  let path=url.pathname.slice('/api/tmdb/'.length);
  let params=url.searchParams;
  if(path==='catalog/week'){
   const week=japanWeek();
   path='discover/movie';
   params=new URLSearchParams({page:params.get('page')||'1',region:'JP',with_release_type:'3|2','release_date.gte':week.start,'release_date.lte':week.end,sort_by:'release_date.asc',include_adult:'false',include_video:'false'});
  }
  if(!/^(configuration|search\/movie|discover\/movie|movie\/now_playing|trending\/movie\/week|watch\/providers\/movie|movie\/[1-9]\d*(?:\/watch\/providers)?)$/.test(path))return json({error:'見つかりません。'},404);
  const key=await storedKey(env);if(!key)return json({error:'映画情報を接続してください。'},503);
  const result=await upstream(path,key,params);if(!result.ok)return json({error:result.status===429?'検索が混み合っています。少し待って再度お試しください。':'映画情報を取得できませんでした。'},result.status===429?429:502);
  return json(await result.json());
 }catch{return json({error:'映画情報に接続できませんでした。時間をおいて再度お試しください。'},503);}
}

const HTML="<!doctype html>\n<html lang=\"ja\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#304d40\"><meta name=\"apple-mobile-web-app-capable\" content=\"yes\"><meta name=\"apple-mobile-web-app-title\" content=\"余韻\"><link rel=\"manifest\" href=\"manifest.webmanifest\"><link rel=\"apple-touch-icon\" href=\"icon-192.png\"><title>余韻 — 私の映画記録</title>\n<style>\n:root{font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif;color:#272b29;background:#f5f4ef}*{box-sizing:border-box}body{margin:0}header{border-bottom:1px solid #dddfd7;padding:24px 6%;display:flex;align-items:center;justify-content:space-between}h1{font-family:serif;font-size:29px;margin:0}small,.muted{color:#747971}button,input,select,textarea{font:inherit}button{cursor:pointer;border:1px solid #d6d9ce;background:transparent;padding:10px 16px;border-radius:7px;color:inherit}button.primary{background:#304d40;color:white;border-color:#304d40}main{max-width:1120px;margin:auto;padding:52px 24px}h2{font-family:serif;font-size:36px;font-weight:500;margin:10px 0 18px}.intro{display:flex;justify-content:space-between;align-items:center;gap:24px}.eyebrow{font-size:11px;letter-spacing:3px;color:#68786c}.stats{display:flex;gap:28px;margin:30px 0 40px}.stats b{font-size:28px;font-weight:500;margin-right:7px}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:24px}.toolbar input{margin-left:auto;min-width:160px}.toolbar .active{background:#304d40;color:white}input,textarea,select{border:1px solid #d6d9ce;border-radius:6px;background:#fffefa;padding:11px;color:#272b29}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.card{background:#fffefa;border:1px solid #dedfd6;border-radius:10px;overflow:hidden}.cover{height:160px;background:linear-gradient(135deg,#344e44,#829081);color:#f4efda;display:flex;align-items:center;justify-content:center;font-family:serif;font-size:42px;letter-spacing:8px}.body{padding:20px}.body h3{margin:9px 0;font-size:20px}.badge{font-size:11px;color:#69756b}.rating{color:#ad803b;letter-spacing:2px}.review{white-space:pre-wrap;line-height:1.8;font-size:14px;overflow-wrap:anywhere}.empty{grid-column:1/-1;text-align:center;border:1px dashed #c9cec2;padding:65px 20px;border-radius:10px}.empty p{color:#747971;font-size:14px;line-height:1.9}footer{margin-top:45px;color:#747971;font-size:12px;line-height:1.9}footer button{font-size:12px;margin:10px 5px 0 0}dialog{border:1px solid #d6d9ce;border-radius:14px;padding:28px;width:min(550px,94vw);background:#f9f8f3}dialog::backdrop{background:#14291dc0}form{display:grid;gap:16px}label{display:grid;gap:7px;font-size:13px}.row{display:flex;gap:12px}.row>*{flex:1}.actions{display:flex;justify-content:flex-end;gap:8px}textarea{resize:vertical;min-height:110px}#notice{color:#80552b;font-size:13px} @media(max-width:700px){main{padding:30px 18px}.grid{grid-template-columns:1fr}.intro{align-items:flex-start}h2{font-size:27px}.intro button{white-space:nowrap;padding:10px}.toolbar input{width:100%;margin:0}.stats{gap:18px}header{padding:20px}header small{font-size:10px}.cover{height:130px}}\n\n@media(max-width:700px){input,select,textarea{font-size:16px;min-width:0}label{min-width:0}.row{flex-wrap:wrap}.row>*{flex-basis:125px}dialog{max-height:90dvh;overflow:auto;padding:22px 18px}main{padding-bottom:calc(30px + env(safe-area-inset-bottom))}.intro{flex-wrap:wrap}.stats{font-size:12px}.stats b{font-size:25px}button{min-height:44px}.toolbar{gap:7px}.intro>button{width:100%}}.install{background:#e9ede5;padding:16px 20px;border-radius:8px;margin:20px 0;font-size:13px;line-height:1.8}.install summary{cursor:pointer;font-weight:600}#app-status{font-size:12px;color:#68786c}\n\n.cover.poster{height:300px;letter-spacing:0;overflow:hidden;background:#dce1d6}.cover img{width:100%;height:100%;object-fit:contain}.movie-info{border-top:1px solid #e1e3d9;padding-top:12px;margin:12px 0;font-size:13px;line-height:1.8}.movie-info p{margin:7px 0}.movie-info summary{cursor:pointer}.providers{background:#eef1e9;padding:12px;border-radius:7px;margin:10px 0}.providers b{display:block}.provider-row{margin:6px 0}.pill{display:inline-block;font-size:11px;border:1px solid #d7dfce;padding:2px 7px;margin:2px;border-radius:20px;background:#fffefa}.source{font-size:11px;color:#70796d}.movie-info a,footer a,#connection a{color:#304d40}.lookup{border:1px solid #d6d9ce;padding:15px;border-radius:8px}.lookup-head{display:flex;gap:8px;align-items:center;justify-content:space-between}.lookup-head strong{font-size:13px}.lookup-results{max-height:340px;overflow:auto}.result{display:flex;gap:12px;width:100%;text-align:left;margin:8px 0;background:#fffefa}.result img{width:52px;height:78px;object-fit:cover}.result span{display:block}.result small{display:block;line-height:1.6}.result strong{font-size:14px}.lookup-note{font-size:12px;line-height:1.8;color:#677260;margin:8px 0}#lookup-status,#connection-status{font-size:13px;line-height:1.8}#lookup-preview{font-size:13px;line-height:1.8}.checkbox{display:flex;align-items:center;gap:8px;line-height:1.8}.checkbox input{width:18px;height:18px}.credit{margin-top:20px;padding-top:15px;border-top:1px solid #dddfd7}.credit img{width:90px;display:block;margin-bottom:8px}#connect{font-size:12px}.pending{color:#8a5d2c}@media(max-width:700px){.cover.poster{height:300px}.lookup-head{flex-wrap:wrap}.lookup-head button{width:100%}}\n\n.grid{align-items:start}.cover.poster{height:auto;aspect-ratio:2/3}.cover img{object-fit:cover}.enrich-tools{margin:20px 0;padding:18px;background:#e9ede5;border-radius:10px}.enrich-tools p{font-size:13px;line-height:1.7}.card details.movie-details>summary{cursor:pointer;font-size:13px;color:#304d40;padding:10px 0}.card .body>small{display:block;overflow-wrap:anywhere}.review-needed{color:#885b24;font-size:12px}.grid{grid-template-columns:repeat(3,minmax(0,1fr))}@media(max-width:700px){.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.body{padding:12px}.body h3{font-size:16px}.card .body>small{font-size:11px}.card button{font-size:12px;padding:8px}.card .cover.poster{height:auto;aspect-ratio:2/3}}\n</style><link rel=\"stylesheet\" href=\"explore.css?v=8\">\n<header><h1>余韻<span style=\"font:12px sans-serif;margin-left:15px;color:#747971\">映画の記録</span></h1><button id=\"connect\">映画情報を接続</button></header>\n<main><div class=\"intro\"><div><span class=\"eyebrow\">A LIFE WITH FILMS</span><h2>観た映画を、私の言葉で。</h2><p class=\"muted\">忘れたくないシーンも、まだ観ぬ一本も。</p></div><button class=\"primary\" id=\"add\">＋ 映画を記録</button></div>\n<details class=\"install\" id=\"install-guide\"><summary>iPhoneのホーム画面に追加する</summary><p>① このページをSafariで開く<br>② 共有メニューから「ホーム画面に追加」を選ぶ<br>③ ホーム画面の「余韻」を開いてから記録を始めてください。</p><p>同じChatGPTアカウントでログインすると、MacとiPhoneで共通の記録を使えます。</p></details><p id=\"app-status\" role=\"status\">共通の映画棚に接続しています…</p><nav class=\"main-tabs\" aria-label=\"メイン\"><button id=\"tab-explore\" aria-pressed=\"false\">映画を探す</button><button id=\"tab-library\" aria-pressed=\"true\" class=\"active\">私の映画棚</button></nav>\n<section id=\"explore\" hidden>\n  <div class=\"section-heading\"><div><span class=\"eyebrow\">FIND YOUR NEXT FILM</span><h2>次に観たい、一本へ。</h2></div><button id=\"explore-connect\">無料接続を設定</button></div>\n  <form id=\"explore-search-form\" class=\"explore-search\"><input id=\"explore-query\" aria-label=\"映画の作品名\" placeholder=\"作品名・原題から映画を探す\"><button class=\"primary\">検索</button></form>\n  <div class=\"explore-filters\">\n    <label>映画の一覧<select id=\"explore-mode\"><option value=\"popular\">TMDBで人気の作品</option><option value=\"now\">上映中</option><option value=\"week\">今週公開</option><option value=\"trending\">トレンド</option></select></label>\n    <label>日本の配信サービス<select id=\"explore-provider\"><option value=\"\">すべて</option></select></label>\n    <label>視聴方法<select id=\"explore-monetization\"><option value=\"flatrate\">見放題</option><option value=\"rent\">レンタル</option><option value=\"buy\">購入</option><option value=\"free\">無料</option><option value=\"ads\">広告付き</option></select></label>\n  </div>\n  <p id=\"explore-status\" role=\"status\" class=\"lookup-note\"></p><div class=\"catalog\" id=\"explore-grid\"></div>\n  <div class=\"pagination\"><button id=\"explore-prev\" hidden>前のページ</button><button id=\"explore-next\" hidden>次のページ</button></div>\n</section><section id=\"library\">\n<div class=\"stats\" id=\"stats\"></div><div class=\"enrich-tools\"><button id=\"enrich-start\">映画棚にポスター・映画情報を追加</button><button id=\"review-filter\">作品の確認が必要な記録</button><p id=\"enrich-status\" role=\"status\">作品名・製作年を照合し、判断できない作品は紐づけずに残します。評価・感想は変更しません。</p></div><div class=\"toolbar\"><button data-filter=\"all\" class=\"active\">すべて</button><button data-filter=\"watched\">鑑賞済み</button><button data-filter=\"want\">観たい</button><input id=\"search\" aria-label=\"記録を検索\" placeholder=\"タイトル・感想を検索\"><select id=\"sort\" aria-label=\"並び順\"><option value=\"updated\">登録・更新順</option><option value=\"date\">鑑賞日順</option><option value=\"rating\">評価順</option></select></div><p id=\"notice\" role=\"status\"></p><section class=\"grid\" id=\"grid\"></section>\n</section><footer>記録は本人専用の保存先へ同期されます。同じChatGPTアカウントでSafari・iPhoneから利用できます。<br>通信が必要です。念のためバックアップも保存できます。<br><button id=\"export\">↓ バックアップを書き出す</button><button id=\"import\">↑ バックアップを読み込む</button><input type=\"file\" id=\"file\" accept=\"application/json,.json\" hidden><div class=\"credit\"><a href=\"https://www.themoviedb.org/\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"tmdb-logo.svg\" alt=\"TMDB\"></a>This product uses the TMDB API but is not endorsed or certified by TMDB.<br>作品情報・画像：TMDB ／ 配信情報：<a href=\"https://www.justwatch.com/jp\" target=\"_blank\" rel=\"noopener noreferrer\">JustWatch</a>（TMDB経由）<br>配信先・料金・見放題の対象は変わります。視聴前に配信サービスで確認してください。</div></footer></main>\n<dialog id=\"modal\"><form id=\"form\"><h2 style=\"font-size:25px;margin:0\">映画の記録</h2><input type=\"hidden\" id=\"recordId\"><label>作品名<input id=\"title\" required maxlength=\"200\" placeholder=\"映画のタイトル\"></label><section class=\"lookup\"><div class=\"lookup-head\"><strong>作品情報・日本の配信サービス</strong><button type=\"button\" id=\"lookup\">作品名で検索</button></div><p class=\"lookup-note\">候補から作品を選ぶと公開情報・ポスター・配信情報を反映します。感想は送信しません。</p><p id=\"lookup-status\" role=\"status\"></p><div id=\"lookup-results\" class=\"lookup-results\"></div><div id=\"lookup-preview\"></div></section><div class=\"row\"><label>ステータス<select id=\"status\"><option value=\"watched\">鑑賞済み</option><option value=\"want\">観たい</option></select></label><label>評価<select id=\"rating\"><option value=\"0\">未評価</option><option value=\"0.1\">★ 0.1</option><option value=\"0.2\">★ 0.2</option><option value=\"0.3\">★ 0.3</option><option value=\"0.4\">★ 0.4</option><option value=\"0.5\">★ 0.5</option><option value=\"0.6\">★ 0.6</option><option value=\"0.7\">★ 0.7</option><option value=\"0.8\">★ 0.8</option><option value=\"0.9\">★ 0.9</option><option value=\"1\">★ 1.0</option><option value=\"1.1\">★ 1.1</option><option value=\"1.2\">★ 1.2</option><option value=\"1.3\">★ 1.3</option><option value=\"1.4\">★ 1.4</option><option value=\"1.5\">★ 1.5</option><option value=\"1.6\">★ 1.6</option><option value=\"1.7\">★ 1.7</option><option value=\"1.8\">★ 1.8</option><option value=\"1.9\">★ 1.9</option><option value=\"2\">★ 2.0</option><option value=\"2.1\">★ 2.1</option><option value=\"2.2\">★ 2.2</option><option value=\"2.3\">★ 2.3</option><option value=\"2.4\">★ 2.4</option><option value=\"2.5\">★ 2.5</option><option value=\"2.6\">★ 2.6</option><option value=\"2.7\">★ 2.7</option><option value=\"2.8\">★ 2.8</option><option value=\"2.9\">★ 2.9</option><option value=\"3\">★ 3.0</option><option value=\"3.1\">★ 3.1</option><option value=\"3.2\">★ 3.2</option><option value=\"3.3\">★ 3.3</option><option value=\"3.4\">★ 3.4</option><option value=\"3.5\">★ 3.5</option><option value=\"3.6\">★ 3.6</option><option value=\"3.7\">★ 3.7</option><option value=\"3.8\">★ 3.8</option><option value=\"3.9\">★ 3.9</option><option value=\"4\">★ 4.0</option><option value=\"4.1\">★ 4.1</option><option value=\"4.2\">★ 4.2</option><option value=\"4.3\">★ 4.3</option><option value=\"4.4\">★ 4.4</option><option value=\"4.5\">★ 4.5</option><option value=\"4.6\">★ 4.6</option><option value=\"4.7\">★ 4.7</option><option value=\"4.8\">★ 4.8</option><option value=\"4.9\">★ 4.9</option><option value=\"5\">★ 5.0</option></select></label></div><div class=\"row\"><label>鑑賞日<input type=\"date\" id=\"date\"></label><label>監督・公開年など<input id=\"meta\" maxlength=\"200\" placeholder=\"自由にメモ\"></label></div><label>感想・メモ<textarea id=\"review\" maxlength=\"20000\" placeholder=\"この映画を観て、何を感じた？\"></textarea></label><div class=\"actions\"><button type=\"button\" id=\"cancel\">キャンセル</button><button class=\"primary\">保存する</button></div></form></dialog>\n<dialog id=\"film-detail\"><div class=\"actions\"><button id=\"film-close\">閉じる</button></div><div id=\"film-content\"></div><p id=\"film-status\" role=\"status\" class=\"lookup-note\"></p><div class=\"actions film-actions\"><button id=\"film-want\">＋ 観たい</button><button id=\"film-record\" class=\"primary\">鑑賞を記録</button></div></dialog>\n<dialog id=\"connection\"><form id=\"connection-form\"><h2 style=\"font-size:25px;margin:0\">映画情報の無料接続</h2><p style=\"font-size:13px;line-height:1.9;margin:0\">TMDBの無料アカウントで映画情報と日本の配信情報を取得します。個人・非商用利用は無料です。</p><ol style=\"font-size:13px;line-height:2;padding-left:20px;margin:0\"><li><a href=\"https://www.themoviedb.org/signup\" target=\"_blank\" rel=\"noopener noreferrer\">TMDBの無料アカウントを作成</a></li><li><a href=\"https://www.themoviedb.org/settings/api\" target=\"_blank\" rel=\"noopener noreferrer\">設定 → API</a>から個人利用のキーを申請（Macでの操作を推奨）</li><li>APIキーまたは「API Read Access Token」を下に貼り付ける</li></ol><label>接続キー<input type=\"password\" id=\"credential\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" required placeholder=\"この画面だけで入力\"></label><input type=\"checkbox\" id=\"remember\" hidden><p class=\"lookup-note\">キーは本人専用の保存先に暗号化して保存します。一度接続すれば、同じアカウントのSafari・iPhoneで入力せず使えます。TMDBへ送るのは作品名・作品IDなどの検索条件だけです。評価や感想、接続キーはバックアップに含めません。</p><p id=\"connection-status\" role=\"status\"></p><div class=\"actions\"><button type=\"button\" id=\"disconnect\">接続について</button><button type=\"button\" id=\"connection-cancel\">閉じる</button><button class=\"primary\" id=\"connection-save\">接続する</button></div></form></dialog><script src=\"films-api.js?v=7\"></script><script src=\"app.js?v=7\"></script><script src=\"explore.js?v=8\"></script><script src=\"enrichment.js?v=7\"></script></html>\n";
const ASSETS={"/app.js":{"type":"text/javascript; charset=utf-8","base64":""},"/enrichment.js":{"type":"text/javascript; charset=utf-8","base64":""},"/explore.css":{"type":"text/css; charset=utf-8","base64":""},"/explore.js":{"type":"text/javascript; charset=utf-8","base64":""},"/films-api.js":{"type":"text/javascript; charset=utf-8","base64":""},"/icon-192.png":{"type":"image/png","base64":""},"/icon-512.png":{"type":"image/png","base64":""},"/manifest.webmanifest":{"type":"application/manifest+json","base64":""},"/tmdb-logo.svg":{"type":"image/svg+xml","base64":""}};
export default {async fetch(request,env){const path=new URL(request.url).pathname;if(env.AUTH_SECRET&&env.AUTH_PASSPHRASE){const gated=await yoinGate(request,env,path);if(gated instanceof Response)return gated;request=gated;}if(path.startsWith("/api/"))return api(request,env);const headers={"Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Referrer-Policy":"same-origin"};if(path==="/"||path==="/index.html")return new Response(HTML,{headers:{...headers,"Content-Type":"text/html; charset=utf-8"}});const asset=ASSETS[path];if(asset)return new Response(Uint8Array.from(atob(asset.base64),c=>c.charCodeAt(0)),{headers:{...headers,"Content-Type":asset.type}});return new Response("Not found",{status:404});}};
